-- ПАЧКА 6-0. Страховка: сверка состава полей перед большими запросами.
-- Ожидаю суммарно 119 полей (95 балльных + 24 текстовых) по 12 таблицам.
-- Если цифры не сойдутся — пришли результат, поправлю запросы ниже.
SELECT h.TABLE_NAME                                              AS tablica,
       SUM(CASE WHEN f.USER_TYPE_ID = 'double' THEN 1 ELSE 0 END) AS ballnyh,
       SUM(CASE WHEN f.USER_TYPE_ID = 'string' THEN 1 ELSE 0 END) AS tekstovyh,
       COUNT(*)                                                   AS vsego
FROM b_user_field f
JOIN b_hlblock_entity h ON f.ENTITY_ID = CONCAT('HLBLOCK_', h.ID)
WHERE h.TABLE_NAME LIKE 'sh\_qest\_h\_%'
GROUP BY h.TABLE_NAME
ORDER BY h.TABLE_NAME;

