  SELECT 'brand' AS anketa, 'UF_HQ_PROD_ANALYT' AS vopros, COUNT(UF_HQ_PROD_ANALYT) AS n, ROUND(AVG(UF_HQ_PROD_ANALYT),2) AS sred, MIN(UF_HQ_PROD_ANALYT) AS mn, MAX(UF_HQ_PROD_ANALYT) AS mx, SUM(CASE WHEN UF_HQ_PROD_ANALYT >= 9 THEN 1 ELSE 0 END) AS ge9, SUM(CASE WHEN UF_HQ_PROD_ANALYT < 7 THEN 1 ELSE 0 END) AS lt7 FROM sh_qest_h_brand UNION ALL
